/* Full-page localisations for the independent research pages. No external translation service is used. */
(()=>{
  const route=location.pathname.replace(/\/+$/,'')||'/';
  const page=route==='/categories'?'categories':route==='/products'?'products':route==='/qc'?'qc':route==='/guides'?'guides':route==='/faq'?'faq':'home';
  if(page==='home')return;
  const root='https://findspreadsheet.com';
  const source=document.querySelector('main');
  if(!source)return;
  const original=source.innerHTML;
  const categories=['shoes','hoodies-sweaters','t-shirts','jackets','pants-shorts','headwear','accessories','jersey','electronics','other-stuff'];
  const data={
    de:{title:'LitBuy Sheet · Unabhängige Recherche',label:'UNABHÄNGIGE RECHERCHE',categoryTitle:'Zehn direkte Wege zur Live-Datenbank.',categoryLead:'Wählen Sie die Kategorie, die zu Ihrer Suche passt. Jeder Weg öffnet die passende FindSpreadsheet-Kollektion; diese Recherche kopiert keine Angebote und verspricht keine Verfügbarkeit.',cats:['Schuhe|Sneaker, Trainer, Slides','Hoodies & Pullover|Fleece, Strick und Layer','T-Shirts|Alltags-Basics','Jacken|Outerwear und technische Layer','Hosen & Shorts|Denim, Cargos und Shorts','Kopfbedeckung|Caps, Beanies und Hüte','Accessoires|Taschen, Uhren und Extras','Trikots|Fußball und Sportswear','Elektronik|Audio, Technik und Zubehör','Weitere Funde|Nützliche Entdeckungen außerhalb der Liste'],productTitle:'Produktdetails vor dem Öffnen einer Live-Route prüfen.',productLead:'Diese Seite hilft beim Vergleichen. Sie verkauft nichts und ersetzt weder die aktuelle Quelle noch die gewählte Variante.',qcTitle:'QC lesen: sichtbar prüfen, offen entscheiden.',qcLead:'Bilder und Notizen können einen Vergleich unterstützen. Sie beweisen weder Authentizität noch Material, Passform, Haltbarkeit oder ein Versandresultat.',guideTitle:'Wie LitBuys Fill&Buy- und Forwarding-Abläufe funktionieren',guideLead:'LitBuy beschreibt öffentlich zwei Wege: eine Kaufanfrage über Fill&Buy und eine Weiterleitung für Pakete, die bereits an das Lager geschickt werden. Beide führen zu Lagerarbeit und internationalem Versand; sie beginnen jedoch mit unterschiedlichen Informationen und Prüfpflichten.',heads:['Mit dem passenden Bestellweg beginnen','Was Fill&Buy laut öffentlicher Darstellung umfasst','Die Aussage zur Produktqualität richtig lesen','Forwarding beginnt mit der Sendungsnummer','Den Lagerstatus als Entscheidungspunkt nutzen','Bilder als Beleg, nicht als Versprechen verwenden','Gebühren, Versand und Rückgabe live prüfen','Eine kurze Routine vor dem nächsten Schritt'],paras:['Notieren Sie vor einer Bestellung die exakte Quellseite, Variante, Menge, Maße, den angezeigten Preis und die Bedingungen des Verkäufers. Eine breite Bezeichnung reicht nicht aus: Links, Optionen und Verfügbarkeit können sich ändern. Diese Notiz macht spätere Vergleiche mit dem Live-Auftrag möglich.','Für Fill&Buy nennt die öffentliche Oberfläche Angaben wie Produktlink, Name, Hinweise, Stückpreis, Menge und inländischen Versand. Die Darstellung trennt Kaufanfrage, Lager/Prüfung, Paketversand und internationale Zahlung. Daraus folgt keine feste Gesamtsumme; lesen Sie die aktuelle Bestätigung, bevor Sie weitergehen.','Die öffentliche Erklärung grenzt die Rolle des Dienstes ab: Sie kann bei Anfrage, Kauf und Drittlogistik helfen, aber Qualität oder Authentizität nicht verifizieren. Prüfen Sie deshalb Materialbehauptungen, Maße, Kompatibilität und Bilder selbst und schreiben Sie Unsicherheit nicht als Zusage um.','Beim Forwarding ist die Sendungsnummer die Identifikation des Pakets. Registrieren Sie sie sorgfältig und folgen Sie dem Auftragsstatus. Erst wenn das Paket als eingelagert angezeigt wird, sind Lagerdaten, Packauswahl, Adresse und die nächste Zahlung praktisch zu beurteilen.','Vergleichen Sie sichtbare Merkmale: Variante, Farbe, Proportionen, Nähte, Hardware, Etiketten und Zubehör. Unterschiedliches Licht oder unvollständige Fotos sind keine sichere Aussage über das Endprodukt. Halten Sie relevante Fragen offen, wenn die Quelle sie nicht beantwortet.','Inländische und internationale Kosten werden in den öffentlichen Schritten getrennt behandelt. Endpreis, Route, Laufzeit, Zulässigkeit und Nachverkaufsoptionen hängen von aktuellen Paket-, Ziel- und Servicebedingungen ab. Eine unabhängige Seite sollte diese Werte nicht vorwegnehmen.','Die nützliche Reihenfolge bleibt: Weg wählen, Quelle und Variante sichern, den Live-Status prüfen, sichtbare Informationen vergleichen und erst dann eine Versandentscheidung treffen. Prüfen Sie bei jeder irreversiblen Zahlung die aktuelle Seite und die geltenden Bedingungen.'],faqTitle:'LitBuy Sheet FAQ: Recherche vor einer Entscheidung',faq:[['Was ist LitBuy Sheet?','Eine unabhängige Rechercheoberfläche, die Produkt- und Kategorienwege zu FindSpreadsheet führt. Sie nimmt keine Bestellungen entgegen.'],['Ist diese Website offiziell?','Nein. Sie fasst öffentlich sichtbare Abläufe als Recherchehilfe zusammen und ersetzt keine Live-Information des Dienstes.'],['Was ist Fill&Buy?','LitBuy beschreibt Fill&Buy als Kaufanfrage mit Produktdaten. Prüfen Sie Link, Variante, Preis und Hinweise vor jeder Zahlung.'],['Was ist Forwarding?','Forwarding betrifft ein Paket, das Sie an ein Lager senden und mit seiner Sendungsnummer registrieren. Der Live-Status bleibt der maßgebliche Checkpunkt.'],['Beweisen Bilder Qualität oder Echtheit?','Nein. Sie können sichtbare Details vergleichen, aber nicht Authentizität, Material, Passform, Haltbarkeit oder ein Ergebnis garantieren.'],['Ist internationaler Versand im ersten Betrag enthalten?','Die öffentlichen Schritte behandeln Kaufanfrage und internationale Versandzahlung getrennt. Lesen Sie den aktuellen Auftrag für die konkrete Berechnung.'],['Kann diese Seite Lieferzeit oder Zoll zusagen?','Nein. Route, Paketdaten, Zielregeln und Dienstbedingungen können sich ändern. Prüfen Sie die aktuelle Route und lokale Anforderungen.'],['Kann ich hier kaufen oder bezahlen?','Nein. Diese Website dient der Recherche; Produktwege öffnen FindSpreadsheet.'],['Welche Informationen sollte ich festhalten?','Quelllink, gewählte Variante, Menge, Maße, Preiszeitpunkt, Sendungsnummer (falls vorhanden), Status und sichtbare Vergleichsnotizen.'],['Wann soll ich eine Entscheidung treffen?','Am besten mit dem aktuellen Auftrag, Lagerstatus und den jeweils sichtbaren Bedingungen – nicht anhand alter Screenshots oder eines allgemeinen Artikels.'],['Gibt es eine Garantie für Rückgabe oder Erstattung?','Nein. Prüfen Sie die aktuellen Regeln, die konkrete Quelle und jede Bestätigung vor dem Handeln.'],['Wohin führen externe Links?','Alle Produkt-, Kategorien- und Datenbankwege dieser Website führen zu FindSpreadsheet.']]},
    fr:{title:'LitBuy Sheet · Recherche indépendante',label:'RECHERCHE INDÉPENDANTE',categoryTitle:'Dix accès directs à la base active.',categoryLead:'Choisissez la catégorie correspondant à votre recherche. Chaque accès ouvre la collection FindSpreadsheet concernée ; ce guide ne copie pas les annonces et ne promet pas de disponibilité.',cats:['Chaussures|Baskets, trainers, slides','Sweats & pulls|Molleton, maille et couches','T-shirts|Essentiels du quotidien','Vestes|Manteaux et couches techniques','Pantalons & shorts|Denim, cargo et shorts','Couvre-chefs|Casquettes, bonnets et chapeaux','Accessoires|Sacs, montres et ajouts','Maillots|Football et sportswear','Électronique|Audio, tech et accessoires','Autres trouvailles|Découvertes utiles hors liste'],productTitle:'Vérifier les détails avant d’ouvrir un accès actif.',productLead:'Cette page aide à comparer. Elle ne vend rien et ne remplace ni la source actuelle ni la variante sélectionnée.',qcTitle:'Lire le QC : vérifier le visible, décider avec prudence.',qcLead:'Les images et notes peuvent aider à comparer. Elles ne prouvent ni l’authenticité, ni la matière, ni la taille, ni la durabilité, ni un résultat de livraison.',guideTitle:'Comprendre les parcours Fill&Buy et forwarding de LitBuy',guideLead:'LitBuy présente publiquement deux parcours : une demande d’achat Fill&Buy et un transfert pour des colis déjà envoyés à l’entrepôt. Tous deux aboutissent à une gestion d’entrepôt et à l’expédition internationale, mais commencent avec des informations et des vérifications différentes.',heads:['Commencer par le parcours correspondant','Ce que la présentation publique dit de Fill&Buy','Lire correctement la limite sur la qualité produit','Le forwarding commence par le numéro de suivi','Utiliser le statut d’entrepôt comme point de décision','Employer les images comme indices, non comme promesses','Vérifier en direct frais, expédition et retours','Une routine courte avant de poursuivre'],paras:['Avant toute demande, conservez la page source exacte, la variante, la quantité, les mesures, le prix affiché et les conditions du vendeur. Un nom général ne suffit pas : les liens, options et disponibilités évoluent. Cette note permet ensuite de comparer avec la commande active.','Pour Fill&Buy, l’interface publique demande notamment lien produit, nom, notes, prix unitaire, quantité et livraison domestique. Elle distingue demande d’achat, stockage ou contrôle, envoi du colis et paiement international. Cela ne constitue pas un total final : relisez la confirmation en cours.','La déclaration publique délimite le rôle du service : il peut aider à demander, acheter et organiser la logistique tierce, sans vérifier qualité ou authenticité. Contrôlez donc vous-même matière, dimensions, compatibilité et images ; ne transformez pas une incertitude en promesse.','Pour le forwarding, le numéro de suivi identifie le colis. Enregistrez-le avec soin et consultez le statut. Ce n’est qu’après l’état stocké que les données d’entrepôt, le choix de colis, l’adresse et la prochaine dépense peuvent être évalués concrètement.','Comparez ce qui est visible : variante, couleur, proportions, coutures, éléments métalliques, étiquettes et accessoires. Un éclairage différent ou des photos incomplètes ne décrivent pas avec certitude le produit final. Laissez ouverte toute question que la source ne résout pas.','Les étapes publiques séparent frais domestiques et paiement international. Prix final, route, délai, admissibilité et après-vente dépendent du colis, de la destination et des conditions actives. Un guide indépendant ne doit pas les annoncer à l’avance.','La séquence utile reste : choisir le parcours, conserver source et variante, consulter le statut actif, comparer les informations visibles, puis décider de l’expédition. À chaque paiement irréversible, vérifiez la page et les conditions actuelles.'],faqTitle:'FAQ LitBuy Sheet : rechercher avant de décider',faq:[['Qu’est-ce que LitBuy Sheet ?','Un espace de recherche indépendant qui oriente les produits et catégories vers FindSpreadsheet. Il ne traite aucune commande.'],['Ce site est-il officiel ?','Non. Il résume des parcours publics à titre de recherche et ne remplace aucune information active du service.'],['Qu’est-ce que Fill&Buy ?','LitBuy présente Fill&Buy comme une demande d’achat avec données produit. Vérifiez lien, variante, prix et notes avant tout paiement.'],['Qu’est-ce que le forwarding ?','Il concerne un colis envoyé à un entrepôt et enregistré avec son suivi. Le statut actif reste le contrôle déterminant.'],['Les images prouvent-elles qualité ou authenticité ?','Non. Elles servent à comparer le visible, sans garantir authenticité, matière, taille, durabilité ou résultat.'],['L’envoi international est-il inclus dès le premier montant ?','Les étapes publiques distinguent demande d’achat et paiement international. Consultez la commande active pour le calcul concret.'],['Ce site promet-il délai ou douane ?','Non. Route, colis, règles du pays et conditions peuvent évoluer. Vérifiez la route active et les exigences locales.'],['Puis-je acheter ou payer ici ?','Non. Ce site sert à rechercher ; les accès produit ouvrent FindSpreadsheet.'],['Quelles informations noter ?','Lien source, variante, quantité, mesures, moment du prix, suivi si applicable, statut et notes de comparaison visibles.'],['Quand décider ?','Avec la commande active, le statut d’entrepôt et les conditions affichées, plutôt qu’avec une ancienne capture ou un article général.'],['Y a-t-il une garantie de retour ?','Non. Consultez les règles actuelles, la source précise et chaque confirmation avant d’agir.'],['Où vont les liens externes ?','Tous les accès produits, catégories et base de ce site vont vers FindSpreadsheet.']]},
    es:{title:'LitBuy Sheet · Investigación independiente',label:'INVESTIGACIÓN INDEPENDIENTE',categoryTitle:'Diez rutas directas a la base activa.',categoryLead:'Elige la categoría que encaje con tu búsqueda. Cada ruta abre la colección correspondiente de FindSpreadsheet; esta guía no copia listados ni promete disponibilidad.',cats:['Calzado|Zapatillas, trainers, slides','Sudaderas y jerséis|Forro polar, punto y capas','Camisetas|Básicos diarios','Chaquetas|Abrigo y capas técnicas','Pantalones y shorts|Denim, cargo y shorts','Gorras y sombreros|Gorras, beanies y sombreros','Accesorios|Bolsos, relojes y extras','Camisetas deportivas|Fútbol y sportswear','Electrónica|Audio, tecnología y accesorios','Otros hallazgos|Descubrimientos útiles fuera de la lista'],productTitle:'Revisa los detalles antes de abrir una ruta activa.',productLead:'Esta página ayuda a comparar. No vende nada ni sustituye la fuente actual o la variante seleccionada.',qcTitle:'Leer QC: revisa lo visible y decide con cautela.',qcLead:'Las imágenes y notas pueden ayudar a comparar. No prueban autenticidad, material, talla, durabilidad ni un resultado de envío.',guideTitle:'Cómo funcionan los flujos Fill&Buy y forwarding de LitBuy',guideLead:'LitBuy presenta públicamente dos flujos: una solicitud de compra llamada Fill&Buy y un reenvío para paquetes que ya se envían al almacén. Ambos terminan con trabajo de almacén y envío internacional, pero empiezan con datos y comprobaciones distintos.',heads:['Empieza por la ruta que corresponde al pedido','Qué indica la presentación pública sobre Fill&Buy','Cómo leer el límite sobre calidad del producto','El forwarding comienza con el número de seguimiento','Usa el estado de almacén como punto de decisión','Usa las imágenes como evidencia, no como promesa','Comprueba en directo tarifas, envío y devoluciones','Una rutina corta antes de continuar'],paras:['Antes de enviar una solicitud, conserva la página fuente exacta, la variante, cantidad, medidas, precio mostrado y condiciones del vendedor. Un nombre amplio no basta: enlaces, opciones y disponibilidad cambian. Esta nota permite comparar más tarde con el pedido activo.','Para Fill&Buy, la pantalla pública pide datos como enlace, nombre, notas, precio unitario, cantidad y envío doméstico. Separa solicitud de compra, almacenamiento o inspección, envío del paquete y pago internacional. Eso no es un total final: revisa la confirmación activa.','La declaración pública delimita el papel del servicio: puede ayudar con consulta, compra y logística de terceros, sin verificar calidad o autenticidad. Revisa por tu cuenta material, medidas, compatibilidad e imágenes; no conviertas una duda en una promesa.','En forwarding, el número de seguimiento identifica el paquete. Regístralo con cuidado y sigue el estado. Solo cuando aparezca almacenado se pueden valorar de forma práctica los datos de almacén, la selección de embalaje, la dirección y el siguiente pago.','Compara lo visible: variante, color, proporciones, costuras, herrajes, etiquetas y accesorios. Distinta luz o fotos incompletas no describen con certeza el producto final. Mantén abierta cualquier pregunta que la fuente no resuelva.','Los pasos públicos separan costes domésticos y pago internacional. Precio final, ruta, plazo, admisibilidad y posventa dependen del paquete, destino y condiciones actuales. Una guía independiente no debe anticiparlos.','El orden útil es: elegir ruta, guardar fuente y variante, revisar estado activo, comparar información visible y decidir el envío. En cada pago irreversible, verifica la página y las condiciones vigentes.'],faqTitle:'FAQ de LitBuy Sheet: investiga antes de decidir',faq:[['¿Qué es LitBuy Sheet?','Una capa de investigación independiente que dirige productos y categorías a FindSpreadsheet. No procesa pedidos.'],['¿Es un sitio oficial?','No. Resume flujos públicos para investigación y no sustituye ninguna información activa del servicio.'],['¿Qué es Fill&Buy?','LitBuy presenta Fill&Buy como una solicitud de compra con datos del producto. Revisa enlace, variante, precio y notas antes de pagar.'],['¿Qué es forwarding?','Es un paquete enviado a un almacén y registrado con su seguimiento. El estado activo es el punto de control decisivo.'],['¿Las imágenes prueban calidad o autenticidad?','No. Sirven para comparar lo visible, no garantizan autenticidad, material, talla, durabilidad ni resultado.'],['¿El envío internacional está incluido en el primer importe?','Los pasos públicos separan solicitud de compra y pago internacional. Consulta el pedido activo para el cálculo concreto.'],['¿Esta web promete plazo o aduanas?','No. Ruta, paquete, reglas de destino y condiciones pueden cambiar. Comprueba la ruta activa y requisitos locales.'],['¿Puedo comprar o pagar aquí?','No. Esta web sirve para investigar; las rutas de producto abren FindSpreadsheet.'],['¿Qué datos debo guardar?','Enlace fuente, variante, cantidad, medidas, momento del precio, seguimiento si aplica, estado y notas visibles.'],['¿Cuándo debo decidir?','Con el pedido activo, estado de almacén y condiciones mostradas, no con una captura antigua ni un artículo general.'],['¿Hay garantía de devolución?','No. Revisa reglas actuales, fuente concreta y cada confirmación antes de actuar.'],['¿Adónde llevan los enlaces externos?','Todas las rutas de productos, categorías y base de este sitio llevan a FindSpreadsheet.']]},
    it:{title:'LitBuy Sheet · Ricerca indipendente',label:'RICERCA INDIPENDENTE',categoryTitle:'Dieci percorsi diretti al database attivo.',categoryLead:'Scegli la categoria che corrisponde alla tua ricerca. Ogni percorso apre la collezione FindSpreadsheet pertinente; questa guida non copia inserzioni e non promette disponibilità.',cats:['Scarpe|Sneaker, trainer, slide','Felpe e maglioni|Pile, maglia e strati','T-shirt|Essenziali quotidiani','Giacche|Capispalla e strati tecnici','Pantaloni e shorts|Denim, cargo e shorts','Copricapo|Cappellini, beanie e cappelli','Accessori|Borse, orologi ed extra','Maglie sportive|Calcio e sportswear','Elettronica|Audio, tecnologia e accessori','Altri ritrovamenti|Scoperte utili oltre l’elenco'],productTitle:'Controlla i dettagli prima di aprire un percorso attivo.',productLead:'Questa pagina aiuta a confrontare. Non vende nulla e non sostituisce la fonte attuale o la variante selezionata.',qcTitle:'Leggere QC: controlla il visibile, decidi con prudenza.',qcLead:'Immagini e note possono aiutare il confronto. Non provano autenticità, materiale, vestibilità, durata o esito della spedizione.',guideTitle:'Come funzionano i flussi Fill&Buy e forwarding di LitBuy',guideLead:'LitBuy presenta pubblicamente due percorsi: una richiesta di acquisto Fill&Buy e il forwarding per pacchi già inviati al magazzino. Entrambi arrivano alla gestione di magazzino e alla spedizione internazionale, ma iniziano con informazioni e verifiche diverse.',heads:['Inizia dal percorso adatto all’ordine','Cosa dice la presentazione pubblica di Fill&Buy','Come leggere il limite sulla qualità del prodotto','Il forwarding inizia dal numero di tracciamento','Usa lo stato di magazzino per decidere','Usa le immagini come riscontro, non come promessa','Controlla in diretta costi, spedizione e resi','Una breve routine prima di proseguire'],paras:['Prima di inviare una richiesta conserva pagina fonte, variante, quantità, misure, prezzo mostrato e condizioni del venditore. Un nome generico non basta: link, opzioni e disponibilità cambiano. Questa nota permette di confrontare in seguito con l’ordine attivo.','Per Fill&Buy la schermata pubblica richiede tra l’altro link, nome, note, prezzo unitario, quantità e spedizione domestica. Separa richiesta, deposito o controllo, invio del pacco e pagamento internazionale. Non è un totale finale: rileggi la conferma attiva.','La dichiarazione pubblica delimita il ruolo del servizio: può aiutare con richiesta, acquisto e logistica terza, ma non verifica qualità o autenticità. Controlla quindi materiale, misure, compatibilità e immagini; non trasformare un dubbio in una promessa.','Nel forwarding il numero di tracciamento identifica il pacco. Registralo con cura e segui lo stato. Solo quando risulta depositato puoi valutare concretamente dati di magazzino, selezione per l’imballaggio, indirizzo e pagamento successivo.','Confronta ciò che è visibile: variante, colore, proporzioni, cuciture, hardware, etichette e accessori. Luce diversa o foto incomplete non descrivono con certezza il prodotto finale. Lascia aperta ogni domanda che la fonte non risolve.','I passaggi pubblici separano costi domestici e pagamento internazionale. Prezzo finale, rotta, tempi, ammissibilità e post-vendita dipendono da pacco, destinazione e condizioni correnti. Una guida indipendente non deve anticiparli.','L’ordine utile resta: scegliere il percorso, conservare fonte e variante, controllare lo stato attivo, confrontare le informazioni visibili e decidere la spedizione. Prima di ogni pagamento irreversibile verifica pagina e condizioni attuali.'],faqTitle:'FAQ LitBuy Sheet: ricerca prima di decidere',faq:[['Cos’è LitBuy Sheet?','Uno spazio di ricerca indipendente che porta prodotti e categorie a FindSpreadsheet. Non elabora ordini.'],['Questo sito è ufficiale?','No. Riassume flussi pubblici per ricerca e non sostituisce informazioni attive del servizio.'],['Cos’è Fill&Buy?','LitBuy presenta Fill&Buy come richiesta d’acquisto con dati prodotto. Controlla link, variante, prezzo e note prima di pagare.'],['Cos’è il forwarding?','Riguarda un pacco inviato a un magazzino e registrato con il tracciamento. Lo stato attivo è il controllo decisivo.'],['Le immagini provano qualità o autenticità?','No. Aiutano a confrontare il visibile, senza garantire autenticità, materiale, vestibilità, durata o risultato.'],['La spedizione internazionale è inclusa nel primo importo?','I passaggi pubblici separano richiesta d’acquisto e pagamento internazionale. Consulta l’ordine attivo per il calcolo concreto.'],['Il sito promette tempi o dogana?','No. Rotta, pacco, regole di destinazione e condizioni possono cambiare. Controlla rotta attiva e requisiti locali.'],['Posso comprare o pagare qui?','No. Questo sito serve per la ricerca; i percorsi prodotto aprono FindSpreadsheet.'],['Quali dati devo conservare?','Link fonte, variante, quantità, misure, momento del prezzo, tracciamento se presente, stato e note visibili.'],['Quando devo decidere?','Con ordine attivo, stato di magazzino e condizioni mostrate, non con una vecchia schermata o un articolo generale.'],['C’è garanzia di reso?','No. Controlla regole attuali, fonte specifica e ogni conferma prima di agire.'],['Dove portano i link esterni?','Tutti i percorsi prodotti, categorie e database di questo sito portano a FindSpreadsheet.']]},
    pt:{title:'LitBuy Sheet · Pesquisa independente',label:'PESQUISA INDEPENDENTE',categoryTitle:'Dez rotas diretas para a base ativa.',categoryLead:'Escolha a categoria que corresponde à sua pesquisa. Cada rota abre a coleção FindSpreadsheet adequada; este guia não copia anúncios nem promete disponibilidade.',cats:['Calçado|Ténis, trainers, slides','Hoodies e malhas|Fleece, malha e camadas','T-shirts|Essenciais diários','Casacos|Outerwear e camadas técnicas','Calças e calções|Denim, cargo e calções','Chapéus e bonés|Bonés, gorros e chapéus','Acessórios|Bolsas, relógios e extras','Camisolas desportivas|Futebol e sportswear','Eletrónica|Áudio, tecnologia e acessórios','Outros achados|Descobertas úteis além da lista'],productTitle:'Verifique os detalhes antes de abrir uma rota ativa.',productLead:'Esta página ajuda a comparar. Não vende nada e não substitui a fonte atual ou a variante escolhida.',qcTitle:'Ler QC: verificar o visível, decidir com cuidado.',qcLead:'Imagens e notas podem ajudar a comparar. Não provam autenticidade, material, tamanho, durabilidade ou um resultado de envio.',guideTitle:'Como funcionam os fluxos Fill&Buy e forwarding da LitBuy',guideLead:'A LitBuy apresenta publicamente dois percursos: um pedido de compra Fill&Buy e o reencaminhamento para encomendas já enviadas ao armazém. Ambos chegam à gestão de armazém e ao envio internacional, mas começam com informação e verificações diferentes.',heads:['Comece pelo percurso adequado ao pedido','O que a apresentação pública diz sobre Fill&Buy','Como ler o limite sobre qualidade do produto','O forwarding começa pelo número de rastreio','Use o estado de armazém como ponto de decisão','Use imagens como indício, não como promessa','Verifique em direto taxas, envio e devoluções','Uma rotina curta antes de continuar'],paras:['Antes de enviar um pedido, guarde a página fonte exata, variante, quantidade, medidas, preço exibido e condições do vendedor. Um nome geral não basta: links, opções e disponibilidade mudam. Esta nota permite comparar depois com a encomenda ativa.','Para Fill&Buy, o ecrã público pede dados como link, nome, notas, preço unitário, quantidade e envio doméstico. Separa pedido, armazenamento ou inspeção, envio da encomenda e pagamento internacional. Isto não é um total final: reveja a confirmação ativa.','A declaração pública delimita o papel do serviço: pode ajudar com consulta, compra e logística de terceiros, sem verificar qualidade ou autenticidade. Confirme por si material, medidas, compatibilidade e imagens; não transforme uma dúvida numa promessa.','No forwarding, o número de rastreio identifica a encomenda. Registe-o cuidadosamente e acompanhe o estado. Só quando aparecer armazenada é possível avaliar de forma prática dados de armazém, seleção de embalagem, morada e pagamento seguinte.','Compare o que é visível: variante, cor, proporções, costuras, ferragens, etiquetas e acessórios. Luz diferente ou imagens incompletas não descrevem com certeza o produto final. Mantenha em aberto qualquer questão que a fonte não esclareça.','Os passos públicos separam custos domésticos e pagamento internacional. Preço final, rota, prazo, admissibilidade e pós-venda dependem da encomenda, destino e condições atuais. Um guia independente não deve antecipá-los.','A ordem útil é: escolher percurso, guardar fonte e variante, verificar estado ativo, comparar informação visível e decidir o envio. Antes de cada pagamento irreversível, confirme página e condições atuais.'],faqTitle:'FAQ LitBuy Sheet: pesquise antes de decidir',faq:[['O que é LitBuy Sheet?','Uma camada de pesquisa independente que encaminha produtos e categorias para FindSpreadsheet. Não processa encomendas.'],['Este site é oficial?','Não. Resume fluxos públicos para pesquisa e não substitui informação ativa do serviço.'],['O que é Fill&Buy?','A LitBuy apresenta Fill&Buy como pedido de compra com dados do produto. Confirme link, variante, preço e notas antes de pagar.'],['O que é forwarding?','É uma encomenda enviada a um armazém e registada com o rastreio. O estado ativo é a verificação decisiva.'],['As imagens provam qualidade ou autenticidade?','Não. Ajudam a comparar o visível, sem garantir autenticidade, material, tamanho, durabilidade ou resultado.'],['O envio internacional está incluído no primeiro valor?','Os passos públicos separam pedido de compra e pagamento internacional. Consulte a encomenda ativa para o cálculo concreto.'],['O site promete prazo ou alfândega?','Não. Rota, encomenda, regras do destino e condições podem mudar. Verifique rota ativa e requisitos locais.'],['Posso comprar ou pagar aqui?','Não. Este site serve para pesquisar; as rotas de produto abrem FindSpreadsheet.'],['Que dados devo guardar?','Link fonte, variante, quantidade, medidas, momento do preço, rastreio se aplicável, estado e notas visíveis.'],['Quando devo decidir?','Com a encomenda ativa, estado de armazém e condições exibidas, não com uma imagem antiga ou artigo geral.'],['Existe garantia de devolução?','Não. Verifique regras atuais, fonte específica e cada confirmação antes de agir.'],['Para onde vão os links externos?','Todas as rotas de produtos, categorias e base deste site vão para FindSpreadsheet.']]},
    nl:{title:'LitBuy Sheet · Onafhankelijk onderzoek',label:'ONAFHANKELIJK ONDERZOEK',categoryTitle:'Tien directe routes naar de live-database.',categoryLead:'Kies de categorie die bij je zoekopdracht past. Elke route opent de passende FindSpreadsheet-collectie; deze gids kopieert geen vermeldingen en belooft geen beschikbaarheid.',cats:['Schoenen|Sneakers, trainers, slides','Hoodies & truien|Fleece, breisel en lagen','T-shirts|Dagelijkse basics','Jassen|Outerwear en technische lagen','Broeken & shorts|Denim, cargo en shorts','Hoofdbedekking|Petjes, beanies en hoeden','Accessoires|Tassen, horloges en extra’s','Shirts|Voetbal en sportkleding','Elektronica|Audio, tech en accessoires','Andere vondsten|Handige ontdekkingen buiten de lijst'],productTitle:'Controleer details vóór je een live-route opent.',productLead:'Deze pagina helpt vergelijken. Hij verkoopt niets en vervangt niet de actuele bron of gekozen variant.',qcTitle:'QC lezen: controleer het zichtbare, beslis zorgvuldig.',qcLead:'Beelden en notities kunnen helpen vergelijken. Ze bewijzen geen authenticiteit, materiaal, pasvorm, duurzaamheid of verzenduitkomst.',guideTitle:'Hoe LitBuy’s Fill&Buy- en forwarding-stromen werken',guideLead:'LitBuy presenteert publiek twee stromen: een Fill&Buy-aankoopaanvraag en forwarding voor pakketten die al naar het magazijn worden verzonden. Beide leiden tot magazijnwerk en internationale verzending, maar starten met verschillende informatie en controles.',heads:['Begin met de juiste bestelroute','Wat de publieke presentatie over Fill&Buy zegt','De grens rond productkwaliteit goed lezen','Forwarding begint met het trackingsnummer','Gebruik magazijnstatus als beslismoment','Gebruik beelden als aanwijzing, niet als belofte','Controleer kosten, verzending en retour live','Een korte routine vóór je doorgaat'],paras:['Bewaar vóór een aanvraag de exacte bronpagina, variant, hoeveelheid, maten, getoonde prijs en verkopersvoorwaarden. Een brede naam is niet genoeg: links, opties en beschikbaarheid veranderen. Deze notitie maakt vergelijking met de actieve order later mogelijk.','Voor Fill&Buy vraagt het publieke scherm onder meer productlink, naam, notities, stukprijs, hoeveelheid en binnenlandse verzending. Het scheidt aankoopaanvraag, opslag of inspectie, pakketverzending en internationale betaling. Dit is geen eindtotaal: lees de actieve bevestiging opnieuw.','De publieke verklaring begrenst de rol van de dienst: die kan helpen met aanvraag, aankoop en logistiek van derden, maar verifieert kwaliteit of authenticiteit niet. Controleer materiaal, maten, compatibiliteit en beelden zelf; verander onzekerheid niet in een belofte.','Bij forwarding identificeert het trackingsnummer het pakket. Registreer het zorgvuldig en volg de status. Pas wanneer het als opgeslagen verschijnt, kun je magazijngegevens, verpakkingskeuze, adres en de volgende betaling praktisch beoordelen.','Vergelijk wat zichtbaar is: variant, kleur, verhoudingen, naden, hardware, labels en accessoires. Ander licht of onvolledige foto’s beschrijven het eindproduct niet zeker. Laat elke vraag open die de bron niet oplost.','De publieke stappen scheiden binnenlandse kosten en internationale betaling. Eindprijs, route, termijn, toelating en nazorg hangen af van pakket, bestemming en actuele voorwaarden. Een onafhankelijke gids mag die niet vooruitlopen.','De bruikbare volgorde blijft: route kiezen, bron en variant bewaren, actieve status controleren, zichtbare informatie vergelijken en dan over verzending beslissen. Controleer bij elke onomkeerbare betaling de actuele pagina en voorwaarden.'],faqTitle:'LitBuy Sheet FAQ: onderzoek vóór je beslist',faq:[['Wat is LitBuy Sheet?','Een onafhankelijke onderzoekslaag die product- en categorieroutes naar FindSpreadsheet leidt. De site verwerkt geen bestellingen.'],['Is dit een officiële site?','Nee. Hij vat publieke stromen samen voor onderzoek en vervangt geen actieve informatie van de dienst.'],['Wat is Fill&Buy?','LitBuy presenteert Fill&Buy als aankoopaanvraag met productgegevens. Controleer link, variant, prijs en notities vóór elke betaling.'],['Wat is forwarding?','Dat is een pakket naar een magazijn sturen en met tracking registreren. De actieve status blijft het beslissende controlemoment.'],['Bewijzen beelden kwaliteit of authenticiteit?','Nee. Ze helpen het zichtbare vergelijken, maar garanderen authenticiteit, materiaal, pasvorm, duurzaamheid of uitkomst niet.'],['Zit internationale verzending in het eerste bedrag?','De publieke stappen scheiden aankoopaanvraag en internationale betaling. Kijk in de actieve order voor de concrete berekening.'],['Belooft deze site termijn of douane?','Nee. Route, pakket, bestemmingsregels en voorwaarden kunnen veranderen. Controleer de actieve route en lokale eisen.'],['Kan ik hier kopen of betalen?','Nee. Deze site is voor onderzoek; productroutes openen FindSpreadsheet.'],['Welke gegevens moet ik bewaren?','Bronlink, variant, hoeveelheid, maten, prijs-moment, tracking indien aanwezig, status en zichtbare vergelijkingsnotities.'],['Wanneer moet ik beslissen?','Met actieve order, magazijnstatus en getoonde voorwaarden, niet met een oude screenshot of algemeen artikel.'],['Is retour of terugbetaling gegarandeerd?','Nee. Controleer actuele regels, de specifieke bron en elke bevestiging vóór je handelt.'],['Waar gaan externe links heen?','Alle product-, categorie- en databaseroutes op deze site gaan naar FindSpreadsheet.']]},
    pl:{title:'LitBuy Sheet · Niezależne badanie',label:'NIEZALEŻNE BADANIE',categoryTitle:'Dziesięć bezpośrednich tras do aktywnej bazy.',categoryLead:'Wybierz kategorię pasującą do wyszukiwania. Każda trasa otwiera właściwą kolekcję FindSpreadsheet; ten przewodnik nie kopiuje ofert i nie obiecuje dostępności.',cats:['Buty|Sneakersy, trainersy, slides','Bluzy i swetry|Polar, dzianina i warstwy','T-shirty|Codzienne podstawy','Kurtki|Odzież wierzchnia i warstwy techniczne','Spodnie i szorty|Denim, cargo i szorty','Nakrycia głowy|Czapki z daszkiem, beanie i kapelusze','Akcesoria|Torby, zegarki i dodatki','Koszulki sportowe|Piłka nożna i sportwear','Elektronika|Audio, technologia i akcesoria','Inne znaleziska|Przydatne odkrycia poza listą'],productTitle:'Sprawdź szczegóły przed otwarciem aktywnej trasy.',productLead:'Ta strona pomaga porównywać. Nie sprzedaje i nie zastępuje aktualnego źródła ani wybranego wariantu.',qcTitle:'Czytanie QC: sprawdź to, co widać, decyduj ostrożnie.',qcLead:'Zdjęcia i notatki mogą pomóc w porównaniu. Nie dowodzą autentyczności, materiału, dopasowania, trwałości ani wyniku wysyłki.',guideTitle:'Jak działają ścieżki Fill&Buy i forwarding LitBuy',guideLead:'LitBuy publicznie przedstawia dwie ścieżki: prośbę zakupową Fill&Buy oraz forwarding dla paczek już wysłanych do magazynu. Obie prowadzą do obsługi magazynowej i wysyłki międzynarodowej, ale zaczynają się od innych danych i kontroli.',heads:['Zacznij od ścieżki właściwej dla zamówienia','Co publiczna prezentacja mówi o Fill&Buy','Jak rozumieć granicę jakości produktu','Forwarding zaczyna się od numeru śledzenia','Użyj statusu magazynu jako momentu decyzji','Traktuj zdjęcia jako wskazówkę, nie obietnicę','Sprawdzaj na żywo opłaty, wysyłkę i zwroty','Krótka rutyna przed następnym krokiem'],paras:['Przed wysłaniem prośby zachowaj dokładną stronę źródłową, wariant, ilość, wymiary, pokazaną cenę i warunki sprzedawcy. Ogólna nazwa nie wystarcza: linki, opcje i dostępność się zmieniają. Ta notatka pozwala potem porównać z aktywnym zamówieniem.','Dla Fill&Buy publiczny ekran prosi m.in. o link, nazwę, uwagi, cenę jednostkową, ilość i wysyłkę krajową. Rozdziela prośbę zakupu, magazynowanie lub kontrolę, wysyłkę paczki i płatność międzynarodową. To nie jest suma końcowa: przeczytaj aktywne potwierdzenie.','Publiczne zastrzeżenie wyznacza rolę usługi: może pomóc w zapytaniu, zakupie i logistyce zewnętrznej, lecz nie weryfikuje jakości ani autentyczności. Samodzielnie sprawdź materiał, wymiary, kompatybilność i zdjęcia; nie zamieniaj niepewności w obietnicę.','W forwardingu numer śledzenia identyfikuje paczkę. Zarejestruj go dokładnie i śledź status. Dopiero po oznaczeniu jako przechowywana można praktycznie ocenić dane magazynowe, wybór pakowania, adres i następną płatność.','Porównaj to, co widać: wariant, kolor, proporcje, szwy, elementy metalowe, etykiety i akcesoria. Inne światło lub niepełne zdjęcia nie opisują pewnie produktu końcowego. Pozostaw otwarte pytanie, którego źródło nie rozstrzyga.','Publiczne kroki rozdzielają koszty krajowe i płatność międzynarodową. Cena końcowa, trasa, termin, dopuszczalność i obsługa posprzedażna zależą od paczki, kraju i aktualnych warunków. Niezależny przewodnik nie powinien ich przewidywać.','Przydatna kolejność to: wybrać ścieżkę, zachować źródło i wariant, sprawdzić aktywny status, porównać widoczne informacje i zdecydować o wysyłce. Przy każdej nieodwracalnej płatności sprawdź aktualną stronę i warunki.'],faqTitle:'FAQ LitBuy Sheet: sprawdź przed decyzją',faq:[['Czym jest LitBuy Sheet?','Niezależna warstwa badawcza prowadząca produkty i kategorie do FindSpreadsheet. Nie obsługuje zamówień.'],['Czy to oficjalna strona?','Nie. Podsumowuje publiczne ścieżki do badań i nie zastępuje aktywnej informacji usługi.'],['Czym jest Fill&Buy?','LitBuy przedstawia Fill&Buy jako prośbę zakupową z danymi produktu. Sprawdź link, wariant, cenę i uwagi przed płatnością.'],['Czym jest forwarding?','To paczka wysłana do magazynu i zarejestrowana przez śledzenie. Aktywny status pozostaje decydującą kontrolą.'],['Czy zdjęcia dowodzą jakości lub autentyczności?','Nie. Pomagają porównać widoczne rzeczy, ale nie gwarantują autentyczności, materiału, dopasowania, trwałości ani wyniku.'],['Czy wysyłka międzynarodowa jest w pierwszej kwocie?','Publiczne kroki rozdzielają prośbę zakupu i płatność międzynarodową. Sprawdź aktywne zamówienie dla konkretnego wyliczenia.'],['Czy strona obiecuje termin lub odprawę celną?','Nie. Trasa, paczka, zasady kraju i warunki mogą się zmienić. Sprawdź aktywną trasę i lokalne wymogi.'],['Czy mogę tu kupić lub zapłacić?','Nie. Strona służy badaniu; trasy produktów otwierają FindSpreadsheet.'],['Jakie dane zachować?','Link źródłowy, wariant, ilość, wymiary, moment ceny, śledzenie jeśli dotyczy, status i widoczne notatki porównawcze.'],['Kiedy podjąć decyzję?','Z aktywnym zamówieniem, statusem magazynu i widocznymi warunkami, a nie ze starym zrzutem czy ogólnym artykułem.'],['Czy zwrot lub refundacja jest gwarantowana?','Nie. Przed działaniem sprawdź aktualne zasady, konkretne źródło i każde potwierdzenie.'],['Dokąd prowadzą linki zewnętrzne?','Wszystkie trasy produktów, kategorii i bazy na tej stronie prowadzą do FindSpreadsheet.']]},
    sv:{title:'LitBuy Sheet · Oberoende research',label:'OBEROENDE RESEARCH',categoryTitle:'Tio direkta vägar till den aktiva databasen.',categoryLead:'Välj kategorin som passar din sökning. Varje väg öppnar rätt FindSpreadsheet-kollektion; den här guiden kopierar inga listningar och lovar ingen tillgänglighet.',cats:['Skor|Sneakers, trainers, slides','Hoodies & tröjor|Fleece, stickat och lager','T-shirts|Vardagsbasics','Jackor|Ytterplagg och tekniska lager','Byxor & shorts|Denim, cargo och shorts','Huvudbonader|Kepsar, beanies och hattar','Accessoarer|Väskor, klockor och tillägg','Tröjor|Fotboll och sportkläder','Elektronik|Ljud, teknik och tillbehör','Övriga fynd|Användbara upptäckter utanför listan'],productTitle:'Kontrollera detaljer innan du öppnar en aktiv väg.',productLead:'Den här sidan hjälper dig att jämföra. Den säljer inget och ersätter inte den aktuella källan eller det valda alternativet.',qcTitle:'Läs QC: kontrollera det synliga och fatta försiktiga beslut.',qcLead:'Bilder och anteckningar kan hjälpa jämförelsen. De bevisar inte äkthet, material, passform, hållbarhet eller ett fraktresultat.',guideTitle:'Så fungerar LitBuys Fill&Buy- och forwardingflöden',guideLead:'LitBuy presenterar offentligt två flöden: en Fill&Buy-köpförfrågan och forwarding för paket som redan skickas till lagret. Båda leder till lagerhantering och internationell frakt, men startar med olika uppgifter och kontroller.',heads:['Börja med vägen som passar beställningen','Vad den offentliga presentationen säger om Fill&Buy','Läs gränsen kring produktkvalitet rätt','Forwarding börjar med spårningsnumret','Använd lagerstatus som beslutspunkt','Använd bilder som underlag, inte löften','Kontrollera avgifter, frakt och returer live','En kort rutin före nästa steg'],paras:['Spara före en förfrågan den exakta källsidan, variant, antal, mått, visat pris och säljarens villkor. Ett brett namn räcker inte: länkar, alternativ och tillgänglighet ändras. Anteckningen gör det möjligt att senare jämföra med den aktiva ordern.','För Fill&Buy ber den offentliga skärmen bland annat om produktlänk, namn, anteckningar, styckepris, antal och inrikes frakt. Den skiljer köpfråga, lagring eller kontroll, paketfrakt och internationell betalning. Det är ingen slutsumma: läs den aktiva bekräftelsen igen.','Den offentliga förklaringen begränsar tjänstens roll: den kan hjälpa med förfrågan, köp och tredjepartslogistik men verifierar inte kvalitet eller äkthet. Kontrollera material, mått, kompatibilitet och bilder själv; gör inte osäkerhet till ett löfte.','I forwarding identifierar spårningsnumret paketet. Registrera det noggrant och följ statusen. Först när paketet visas som lagrat kan lageruppgifter, packningsval, adress och nästa betalning bedömas praktiskt.','Jämför det som syns: variant, färg, proportioner, sömmar, beslag, etiketter och tillbehör. Annat ljus eller ofullständiga bilder beskriver inte slutprodukten säkert. Låt frågor som källan inte löser vara öppna.','De offentliga stegen skiljer inrikes kostnader och internationell betalning. Slutpris, rutt, tid, tillåtlighet och efterservice beror på paket, destination och aktuella villkor. En oberoende guide ska inte förutse dem.','Den användbara ordningen är: välj väg, spara källa och variant, kontrollera aktiv status, jämför synlig information och besluta sedan om frakt. Kontrollera aktuell sida och villkor före varje oåterkallelig betalning.'],faqTitle:'LitBuy Sheet FAQ: undersök före beslut',faq:[['Vad är LitBuy Sheet?','Ett oberoende researchlager som leder produkt- och kategorivägar till FindSpreadsheet. Sidan hanterar inga order.'],['Är detta en officiell sida?','Nej. Den sammanfattar offentliga flöden för research och ersätter inte aktiv information från tjänsten.'],['Vad är Fill&Buy?','LitBuy beskriver Fill&Buy som en köpförfrågan med produktuppgifter. Kontrollera länk, variant, pris och anteckningar före betalning.'],['Vad är forwarding?','Det är ett paket som skickas till ett lager och registreras med spårning. Aktiv status är den avgörande kontrollen.'],['Bevisar bilder kvalitet eller äkthet?','Nej. De hjälper dig att jämföra det synliga, men garanterar inte äkthet, material, passform, hållbarhet eller resultat.'],['Ingår internationell frakt i första beloppet?','De offentliga stegen skiljer köpfråga och internationell betalning. Se den aktiva ordern för den konkreta beräkningen.'],['Lovar sidan leveranstid eller tull?','Nej. Rutt, paket, destinationsregler och villkor kan ändras. Kontrollera aktiv rutt och lokala krav.'],['Kan jag köpa eller betala här?','Nej. Sidan är till för research; produktvägar öppnar FindSpreadsheet.'],['Vilka uppgifter ska jag spara?','Källänk, variant, antal, mått, tidpunkt för pris, spårning om den finns, status och synliga jämförelseanteckningar.'],['När ska jag besluta?','Med aktiv order, lagerstatus och visade villkor, inte med en gammal skärmbild eller allmän artikel.'],['Är retur eller återbetalning garanterad?','Nej. Kontrollera aktuella regler, den specifika källan och varje bekräftelse före handling.'],['Vart leder externa länkar?','Alla produkt-, kategori- och databasvägar på den här sidan leder till FindSpreadsheet.']]}
  };
  const articleNotes={
    de:['Vergleichen Sie die veröffentlichte Information jedes Mal mit der aktuellen Bestellansicht. Ein alter Screenshot, eine Suchzeile oder ein kurzer Produktname zeigt weder den gewählten Artikel noch die Bedingungen, die im Moment der Zahlung gelten.','Ein nachvollziehbarer Verlauf ist nützlicher als eine schnelle Annahme: bewahren Sie Link, Variante, Bestellreferenz und sichtbare Beobachtungen zusammen auf. So können Sie eine offene Frage vor der nächsten Entscheidung gezielt prüfen.','Prüfen Sie bei jedem Paket die aktuelle Routendarstellung, die Zieladresse und die vom System angezeigten Paketdaten. Diese Informationen sind konkreter als allgemeine Preis- oder Laufzeitangaben aus einem unabhängigen Artikel.','Diese Recherche erklärt den Ablauf, trifft aber keine Entscheidung für eine einzelne Bestellung. Verfügbarkeit, Verkäuferantwort, Lagerstatus und die für Ihr Ziel erlaubte Route müssen in der jeweiligen Live-Ansicht bestätigt werden.'],
    fr:['Comparez à chaque étape les informations publiées avec la vue active de la commande. Une ancienne capture, une ligne de recherche ou un titre court ne montre ni la variante choisie ni les conditions au moment du paiement.','Un dossier traçable vaut mieux qu’une supposition rapide : conservez lien, variante, référence de commande et observations visibles. Vous pourrez ainsi vérifier précisément une question avant la décision suivante.','Pour chaque colis, consultez la route active, l’adresse de destination et les données de colis affichées par le système. Ces éléments sont plus concrets qu’un prix ou délai général cité dans un article indépendant.','Cette recherche décrit un déroulement, sans décider pour une commande particulière. Disponibilité, réponse du vendeur, statut d’entrepôt et route autorisée vers votre destination doivent être confirmés dans la vue active.'],
    es:['En cada etapa compara la información publicada con la vista activa del pedido. Una captura antigua, una línea de búsqueda o un título corto no muestran la variante elegida ni las condiciones vigentes al pagar.','Un registro comprobable vale más que una suposición rápida: guarda enlace, variante, referencia del pedido y observaciones visibles. Así podrás revisar una duda concreta antes de la siguiente decisión.','Para cada paquete consulta la ruta activa, la dirección de destino y los datos de paquete mostrados por el sistema. Son datos más concretos que un precio o plazo general citado en un artículo independiente.','Esta investigación explica el flujo, pero no decide por un pedido individual. Disponibilidad, respuesta del vendedor, estado de almacén y ruta permitida para tu destino deben confirmarse en la vista activa.'],
    it:['A ogni passaggio confronta le informazioni pubblicate con la vista attiva dell’ordine. Una vecchia schermata, una riga di ricerca o un titolo breve non mostrano né la variante scelta né le condizioni valide al pagamento.','Un registro verificabile vale più di un’ipotesi rapida: conserva link, variante, riferimento ordine e osservazioni visibili. Potrai così controllare una domanda precisa prima della decisione successiva.','Per ogni pacco controlla la rotta attiva, l’indirizzo di destinazione e i dati del pacco mostrati dal sistema. Sono elementi più concreti di un prezzo o tempo generale citato da un articolo indipendente.','Questa ricerca descrive il flusso, ma non decide per un ordine specifico. Disponibilità, risposta del venditore, stato di magazzino e rotta consentita verso la tua destinazione vanno confermati nella vista attiva.'],
    pt:['Em cada etapa compare a informação publicada com a vista ativa da encomenda. Uma captura antiga, uma linha de pesquisa ou um título curto não mostram a variante escolhida nem as condições válidas no momento do pagamento.','Um registo verificável vale mais do que uma suposição rápida: guarde link, variante, referência da encomenda e observações visíveis. Assim poderá confirmar uma questão concreta antes da decisão seguinte.','Para cada encomenda consulte a rota ativa, a morada de destino e os dados da embalagem mostrados pelo sistema. Estes elementos são mais concretos do que um preço ou prazo geral citado num artigo independente.','Esta pesquisa explica o fluxo, mas não decide por uma encomenda individual. Disponibilidade, resposta do vendedor, estado de armazém e rota permitida para o destino devem ser confirmados na vista ativa.'],
    nl:['Vergelijk bij elke stap de gepubliceerde informatie met de actieve orderweergave. Een oude screenshot, zoekregel of korte titel toont noch de gekozen variant noch de voorwaarden die tijdens betaling gelden.','Een controleerbaar dossier is beter dan een snelle aanname: bewaar link, variant, orderreferentie en zichtbare observaties samen. Zo kun je een gerichte vraag controleren vóór de volgende beslissing.','Controleer bij elk pakket de actieve route, het bestemmingsadres en de pakketgegevens die het systeem toont. Die zijn concreter dan een algemene prijs- of tijdsaanduiding uit een onafhankelijk artikel.','Dit onderzoek beschrijft de stroom, maar beslist niet voor een afzonderlijke order. Beschikbaarheid, verkopersreactie, magazijnstatus en toegestane route naar jouw bestemming moeten in de actieve weergave worden bevestigd.'],
    pl:['Na każdym etapie porównuj opublikowane informacje z aktywnym widokiem zamówienia. Stary zrzut ekranu, fraza wyszukiwania lub krótki tytuł nie pokazują wybranego wariantu ani warunków obowiązujących podczas płatności.','Weryfikowalny zapis jest lepszy niż szybkie założenie: zachowaj link, wariant, numer zamówienia i widoczne obserwacje. Dzięki temu sprawdzisz konkretne pytanie przed kolejną decyzją.','Dla każdej paczki sprawdź aktywną trasę, adres docelowy i dane paczki wyświetlane przez system. Są one bardziej konkretne niż ogólna cena lub termin z niezależnego artykułu.','To badanie opisuje przepływ, ale nie podejmuje decyzji za pojedyncze zamówienie. Dostępność, odpowiedź sprzedawcy, status magazynu i dozwolona trasa do celu muszą być potwierdzone w aktywnym widoku.'],
    sv:['Jämför vid varje steg den publicerade informationen med den aktiva ordervyn. En gammal skärmbild, sökrad eller kort titel visar varken vald variant eller de villkor som gäller när du betalar.','Ett verifierbart underlag är bättre än ett snabbt antagande: spara länk, variant, orderreferens och synliga observationer tillsammans. Då kan du kontrollera en specifik fråga före nästa beslut.','Kontrollera för varje paket den aktiva rutten, destinationsadressen och paketdata som systemet visar. De är mer konkreta än ett allmänt pris eller tidsintervall i en oberoende artikel.','Den här researchen beskriver flödet men beslutar inte för en enskild order. Tillgänglighet, säljarens svar, lagerstatus och tillåten rutt till din destination måste bekräftas i den aktiva vyn.']
  };
  const faqNotes={de:'Prüfen Sie die aktuelle Auftrags- oder Richtlinienansicht, bevor Sie eine Zahlung oder Versandentscheidung treffen.',fr:'Consultez toujours la commande ou règle active avant de payer ou d’envoyer un colis.',es:'Consulta siempre el pedido o la norma activa antes de pagar o enviar un paquete.',it:'Consulta sempre l’ordine o la regola attiva prima di pagare o spedire un pacco.',pt:'Consulte sempre a encomenda ou regra ativa antes de pagar ou enviar uma encomenda.',nl:'Controleer altijd de actieve order of regel vóór je betaalt of een pakket verstuurt.',pl:'Przed płatnością lub wysyłką paczki zawsze sprawdź aktywne zamówienie albo zasadę.',sv:'Kontrollera alltid den aktiva ordern eller regeln innan du betalar eller skickar ett paket.'};
  const closingNotes={de:'Quellen und Bedingungen können sich ändern. Entscheidend bleibt stets die aktuelle Information im jeweiligen Auftrag.',fr:'Les sources et conditions peuvent évoluer. La référence reste toujours l’information active de la commande concernée.',es:'Las fuentes y condiciones pueden cambiar. La referencia es siempre la información activa del pedido correspondiente.',it:'Fonti e condizioni possono cambiare. Il riferimento resta sempre l’informazione attiva del relativo ordine.',pt:'Fontes e condições podem mudar. A referência continua a ser a informação ativa da encomenda correspondente.',nl:'Bronnen en voorwaarden kunnen veranderen. De actieve informatie van de betreffende order blijft altijd leidend.',pl:'Źródła i warunki mogą się zmieniać. Decydująca pozostaje zawsze aktywna informacja o danym zamówieniu.',sv:'Källor och villkor kan ändras. Den aktiva informationen för den aktuella ordern är alltid vägledande.'};
  const labels={en:'English',de:'Deutsch',fr:'Français',es:'Español',it:'Italiano',pt:'Português',nl:'Nederlands',pl:'Polski',sv:'Svenska'};
  const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const ui={de:{category:'KATEGORIEN',desk:'PRODUKT-CHECK',qc:'QC-LEITFADEN',review:'GEPRÜFT',date:'22. SEPTEMBER 2026',open:'FindSpreadsheet-Datenbank öffnen'},fr:{category:'CATÉGORIES',desk:'BUREAU PRODUIT',qc:'GUIDE QC',review:'VÉRIFIÉ',date:'22 SEPTEMBRE 2026',open:'Ouvrir la base FindSpreadsheet'},es:{category:'CATEGORÍAS',desk:'MESA DE PRODUCTO',qc:'GUÍA QC',review:'REVISADO',date:'22 SEPTIEMBRE 2026',open:'Abrir la base FindSpreadsheet'},it:{category:'CATEGORIE',desk:'DESK PRODOTTO',qc:'GUIDA QC',review:'VERIFICATO',date:'22 SETTEMBRE 2026',open:'Apri il database FindSpreadsheet'},pt:{category:'CATEGORIAS',desk:'MESA DE PRODUTO',qc:'GUIA QC',review:'REVISADO',date:'22 SETEMBRO 2026',open:'Abrir a base FindSpreadsheet'},nl:{category:'CATEGORIEËN',desk:'PRODUCTDESK',qc:'QC-GIDS',review:'GECONTROLEERD',date:'22 SEPTEMBER 2026',open:'FindSpreadsheet-database openen'},pl:{category:'KATEGORIE',desk:'SZCZEGÓŁY PRODUKTU',qc:'PRZEWODNIK QC',review:'SPRAWDZONO',date:'22 WRZEŚNIA 2026',open:'Otwórz bazę FindSpreadsheet'},sv:{category:'KATEGORIER',desk:'PRODUKTDETALJER',qc:'QC-GUIDE',review:'GRANSKAD',date:'22 SEPTEMBER 2026',open:'Öppna FindSpreadsheet-databasen'}};
  const action=lang=>ui[lang]?.open||'Open the FindSpreadsheet database';
  function categoryPage(t){const x=ui[document.documentElement.lang];return `<p class="eyebrow">${t.label} / ${x.category}</p><h1>${t.categoryTitle}</h1><p class="lead">${t.categoryLead}</p><div class="product-route-grid">${t.cats.map((v,i)=>{const [n,d]=v.split('|');return `<a href="${root}/${categories[i]}/"><span>${String(i+1).padStart(2,'0')}</span><b>${esc(n)}</b><em>${esc(d)}</em></a>`}).join('')}</div><a class="button-dark" href="${root}/AllProducts/">${action(document.documentElement.lang)}</a>`}
  function productPage(t){const x=ui[document.documentElement.lang],cards=[[t.productTitle,t.productLead],[t.heads[0],t.paras[0]],[t.heads[4],t.paras[4]],[t.heads[6],t.paras[5]]];return `<p class="eyebrow">${t.label} / ${x.desk}</p><h1>${t.productTitle}</h1><p class="lead">${t.productLead}</p><section class="check-grid">${cards.map(([h,p],i)=>`<article><span>${String(i+1).padStart(2,'0')}</span><h2>${h}</h2><p>${p}</p></article>`).join('')}</section><a class="button-dark" href="${root}/AllProducts/">${action(document.documentElement.lang)}</a>`}
  function qcPage(t){const x=ui[document.documentElement.lang];return `<p class="eyebrow">${t.label} / ${x.qc}</p><h1>${t.qcTitle}</h1><p class="lead">${t.qcLead}</p><section class="check-grid">${t.heads.slice(0,6).map((h,i)=>`<article><span>${String(i+1).padStart(2,'0')}</span><h2>${h}</h2><p>${t.paras[i]}</p></article>`).join('')}</section><p class="article-note">${t.paras[6]}</p><a class="button-dark" href="${root}/AllProducts/">${action(document.documentElement.lang)}</a>`}
  function guidePage(t){const lang=document.documentElement.lang,x=ui[lang],notes=articleNotes[lang];return `<p class="eyebrow">${t.label} / ${x.review} ${x.date}</p><h1>${t.guideTitle}</h1><p class="lead">${t.guideLead}</p><p class="article-note">${t.qcLead} ${t.faq[1][1]}</p>${t.heads.map((h,i)=>`<h2>${h}</h2><p>${t.paras[i%t.paras.length]}</p><p>${t.paras[(i+1)%t.paras.length]}</p><p>${notes[i%notes.length]}</p><p>${notes[(i+1)%notes.length]}</p><p>${notes[(i+2)%notes.length]}</p>`).join('')}<p class="article-note">${closingNotes[lang]}</p><a class="button-dark" href="${root}/">${action(lang)}</a>`}
  function faqPage(t){const lang=document.documentElement.lang,note=faqNotes[lang];return `<p class="eyebrow">${t.label} / FAQ</p><h1>${t.faqTitle}</h1><p class="lead">${t.guideLead}</p><section class="faq-list">${t.faq.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p><p>${note}</p></details>`).join('')}</section><a class="button-dark" href="${root}/AllProducts/">${action(lang)}</a>`}
  function render(lang){document.documentElement.lang=lang||'en';if(page==='guides'||page==='faq'){source.innerHTML=original;return}const t=data[lang];if(!t){source.innerHTML=original;return}document.title=t.title;source.innerHTML=page==='categories'?categoryPage(t):page==='products'?productPage(t):qcPage(t)}
  const select=document.querySelector('#language-select');
  if(!select)return;
  const current=select.value||localStorage.getItem('litbuy-sheet-language')||'en';
  render(current);
  select.addEventListener('change',()=>render(select.value));
})();
